    "ungroupDesc": "স্ট্যাকে আইটেমগুলি আলাদা করতে চান? স্ট্যাক প্রসারিত করতে ক্লিক করুন, তারপর যেকোনো সাবআইটেম স্ক্রিনের বাম প্রান্তে টেনে আনুন। একটি উজ্জ্বল কোরাল বার আবির্ভূত হবে—আইটেমটিকে স্বতন্ত্র কার্ড হিসাবে ফিরে আনতে এতে ছেড়ে দিন।",
